      authored?.plural ??
      (Object.hasOwn(STYLE1_IRREGULAR_PLURALS, noun)
        ? STYLE1_IRREGULAR_PLURALS[noun]
        : undefined) ??
      [`${noun}s`, `${noun}es`, noun.replace(/([^aeiou])y$/, "$1ies")].find(
        (form) => form !== noun && englishWordInfo(form)?.plural,
      );
